<h1 class="h">Úkoly</h1><div class="sub">Termíny, priority a přiřazení.</div><div class="card"><form class="row" method="post" action="/tasks/save"><input type="hidden" name="_csrf" value="<?=App\Core\Auth::csrf()?>"><input name="title" placeholder="Nový úkol" required><input name="due_at" type="datetime-local"><select name="priority"><option>normal</option><option>high</option><option>urgent</option></select><button class="btn primary">Přidat</button></form></div><div style="height:16px"></div><?php foreach($tasks as $t):?><div class="card" style="margin-bottom:10px"><b><?=View::e($t['title'])?></b> · <?=View::e($t['priority'])?><div class="sub"><?=View::e($t['due_at'])?></div><?php if($t['status']!=='done'):?><form method="post" action="/tasks/<?=$t['id']?>/done"><input type="hidden" name="_csrf" value="<?=App\Core\Auth::csrf()?>"><button class="btn">Hotovo</button></form><?php endif;?></div><?php endforeach;?>